// GENERATED FILE - do not edit netlify/edge-functions/api-chat.js by hand.
// Source template: netlify-build/templates/api-chat.template.js
// Regenerated by scripts/fetch-laws.mjs on every build - a JS port of the
// Python app (app/main.py + app/llm_router.py + app/retrieval.py +
// app/i18n.py) for Netlify Edge Functions, which can't run Python.
//
// Two deliberate differences from the Python version, both driven by
// Netlify Edge Functions needing to send response headers within ~40s
// (see DEADLINE_BUDGET_MS below), whereas real Groq/Gemini calls were
// observed taking up to ~25-30s on their own due to model "thinking"
// overhead - see the project's README for the full writeup:
//   1. Retrieval always uses the local lexical/glossary search (no
//      network call) instead of an LLM "selector" call. The Python
//      version only falls back to this when every provider is exhausted;
//      here it's the only retrieval method, so the full time budget goes
//      to one LLM call (the answer) instead of being split across two.
//   2. Each provider hop gets a longer per-hop timeout than would be safe
//      if a selector call had to run first too - see DEFAULT_HOP_TIMEOUT_MS.
// If the LLM call still doesn't finish in time, the request degrades to
// the same raw-text fallback the Python version uses when every provider
// is exhausted, instead of the platform hard-killing the request with no
// answer at all.

// ---------------------------------------------------------------------
// Provider config (app/config.py)
// ---------------------------------------------------------------------
const PROVIDERS = {
  groq: {
    baseUrl: "https://api.groq.com/openai/v1",
    apiKeyEnv: "GROQ_API_KEY",
    defaultModels: ["openai/gpt-oss-120b", "openai/gpt-oss-20b"],
  },
  gemini: {
    baseUrl: "https://generativelanguage.googleapis.com/v1beta/openai",
    apiKeyEnv: "GEMINI_API_KEY",
    defaultModels: ["gemini-3.6-flash", "gemini-3.5-flash"],
  },
  openrouter: {
    baseUrl: "https://openrouter.ai/api/v1",
    apiKeyEnv: "OPENROUTER_API_KEY",
    defaultModels: [
      "nvidia/nemotron-3.5-lightning:free",
      "minimax/minimax-m3:free",
      "z-ai/glm-5-2:free",
      "liquid/lfm-2.5-2.6b:free",
    ],
    extraHeaders: {
      "HTTP-Referer": "https://localhost/worker-council-app",
      "X-Title": "Worker Council Assistant (Germany)",
    },
  },
};
// Gemini's free tier is only 20 requests/day per model (confirmed via its
// own 429 response), so trying it before OpenRouter (20/min, 50/day) just
// wastes a hop attempt on something almost always exhausted. Groq first
// (best free-tier limits), OpenRouter second, Gemini last as a rarely-
// useful final fallback.
const PROVIDER_PRIORITY = ["groq", "openrouter", "gemini"];

function getHopOrder() {
  const override = (Netlify.env.get("LLM_HOP_ORDER") || "").trim();
  if (override) {
    const hops = [];
    for (const entry of override.split(",")) {
      const trimmed = entry.trim();
      if (!trimmed || !trimmed.includes(":")) continue;
      const sepIndex = trimmed.indexOf(":");
      const providerName = trimmed.slice(0, sepIndex).trim();
      const model = trimmed.slice(sepIndex + 1).trim();
      if (PROVIDERS[providerName]) hops.push([providerName, model]);
    }
    return hops;
  }
  const hops = [];
  for (const providerName of PROVIDER_PRIORITY) {
    const spec = PROVIDERS[providerName];
    if (!Netlify.env.get(spec.apiKeyEnv)) continue;
    for (const model of spec.defaultModels) hops.push([providerName, model]);
  }
  return hops;
}

// ---------------------------------------------------------------------
// LLM router (app/llm_router.py), with a shared wall-clock deadline
// ---------------------------------------------------------------------
class AllProvidersExhaustedError extends Error {}

const RATE_LIMIT_STATUS = new Set([429]);
const AUTH_STATUS = new Set([401, 403]);
// Generous per-hop timeout: real Groq/Gemini calls have been observed
// taking up to ~25-30s on their own (model "thinking" overhead), and
// since retrieval no longer costs a separate LLM call (see file header),
// the full deadline budget is available for this one call.
const DEFAULT_HOP_TIMEOUT_MS = 25000;
const MIN_HOP_BUDGET_MS = 3000;
const SAFETY_MARGIN_MS = 500;

async function callOneHop(providerName, model, messages, temperature, maxTokens, timeoutMs) {
  const spec = PROVIDERS[providerName];
  const apiKey = Netlify.env.get(spec.apiKeyEnv);
  if (!apiKey) {
    throw new Error(`No API key set for ${providerName} (${spec.apiKeyEnv})`);
  }

  const url = `${spec.baseUrl.replace(/\/$/, "")}/chat/completions`;
  const headers = {
    Authorization: `Bearer ${apiKey}`,
    "Content-Type": "application/json",
    ...(spec.extraHeaders || {}),
  };
  const body = { model, messages, temperature, max_tokens: maxTokens };

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  let resp;
  try {
    resp = await fetch(url, {
      method: "POST",
      headers,
      body: JSON.stringify(body),
      signal: controller.signal,
    });
  } catch (err) {
    if (err.name === "AbortError") {
      throw new Error(`${providerName}:${model} timed out after ${timeoutMs}ms`);
    }
    throw err;
  } finally {
    clearTimeout(timer);
  }

  if (RATE_LIMIT_STATUS.has(resp.status)) {
    throw new Error(`${providerName}:${model} rate-limited (HTTP 429)`);
  }
  if (AUTH_STATUS.has(resp.status)) {
    throw new Error(`${providerName}:${model} auth failed (HTTP ${resp.status}) - check the API key`);
  }
  if (resp.status >= 400) {
    const text = await resp.text().catch(() => "");
    throw new Error(`${providerName}:${model} HTTP ${resp.status}: ${text.slice(0, 300)}`);
  }

  const data = await resp.json();
  const content = data && data.choices && data.choices[0] && data.choices[0].message
    ? data.choices[0].message.content
    : undefined;
  if (typeof content !== "string") {
    throw new Error(`${providerName}:${model} returned an unexpected response shape`);
  }
  return content;
}

async function chatCompletion(messages, { temperature = 0.2, maxTokens = 900, deadline } = {}) {
  const hopOrder = getHopOrder();
  if (!hopOrder.length) {
    throw new AllProvidersExhaustedError(
      "No LLM provider API keys are configured. Set at least one of GROQ_API_KEY, " +
        "GEMINI_API_KEY, OPENROUTER_API_KEY as a Netlify environment variable " +
        "(scope: Functions)."
    );
  }

  const tried = [];
  let lastError = null;

  for (const [providerName, model] of hopOrder) {
    const remaining = deadline ? deadline - Date.now() : Infinity;
    if (remaining < MIN_HOP_BUDGET_MS) {
      lastError = lastError || new Error("Request deadline budget exhausted before every hop was tried");
      break;
    }
    const hopTimeout = Math.min(DEFAULT_HOP_TIMEOUT_MS, Math.max(MIN_HOP_BUDGET_MS, remaining - SAFETY_MARGIN_MS));
    const hopLabel = `${providerName}:${model}`;
    tried.push(hopLabel);
    try {
      const text = await callOneHop(providerName, model, messages, temperature, maxTokens, hopTimeout);
      return { text, provider: providerName, model };
    } catch (err) {
      lastError = err;
    }
  }

  throw new AllProvidersExhaustedError(
    `All ${tried.length} configured free-LLM hops failed or are rate-limited right now: ` +
      `${tried.join(", ")}. Last error: ${lastError ? lastError.message : "none"}`
  );
}

