function expandQueryTerms(query, language) {
  const q = query.toLowerCase();
  const terms = new Set();
  // Only add the query's own raw words when it's German: they're then
  // genuine German legal terms worth substring-matching directly. For an
  // English query, a raw word like "and" or "does" would otherwise
  // spuriously substring-match unrelated German words (e.g. "and" inside
  // "andere"/"anderen"/"Gegenstand"), swamping the real signal from the
  // glossary below with noise.
  if (language === "de") {
    for (const w of q.match(/[a-zäöüß]+/g) || []) terms.add(w);
  }
  const queryWords = q.match(/[a-z]+/g) || [];
  for (const [phrase, deTerms] of Object.entries(GLOSSARY)) {
    let matched;
    if (phrase.includes(" ")) {
      // Multi-word phrases ("personal data", "works council") are compound
      // concepts, not easily stemmed - match as a literal substring.
      matched = q.includes(phrase);
    } else {
      // Single-word keys match by shared prefix, not exact word or full
      // startsWith, so "dismissed"/"dismissal"/"dismissing" all hit the
      // same glossary entry even though none is a prefix of another
      // (they share only "dismiss", 7 of 9-10 letters). Without this, a
      // query using an unlisted inflection (e.g. asking "dismissed" when
      // only "dismissal" was in the glossary) loses its only
      // discriminating term and falls back to whatever generic word (like
      // "works council") happens to be common to nearly every section,
      // making the ranking essentially noise.
      matched = queryWords.some((w) => {
        if (w.length < 4 || phrase.length < 4) return false;
        let i = 0;
        while (i < w.length && i < phrase.length && w[i] === phrase[i]) i++;
        return i >= 4;
      });
    }
    if (matched) for (const t of deTerms) terms.add(t);
  }
  return terms;
}

// Caps how many times any single term can count towards a section's
// score. Without this, a broad glossary term like "employer" -> "arbeitgeber"
// (ubiquitous in legal text) can rack up a huge raw count and drown out a
// rarer, far more diagnostic term like "löschung" that only appears a
// handful of times but pinpoints the actually relevant section.
const MAX_TERM_CONTRIBUTION = 4;

function lexicalSearch(query, language, topK = 5) {
  const terms = [...expandQueryTerms(query, language)].filter((t) => t.length > 2);
  if (!terms.length) return [];
  const scored = [];
  for (const s of ALL_SECTIONS) {
    const haystack = `${s.title_de} ${s.text_de}`.toLowerCase();
    let score = 0;
    for (const t of terms) {
      const count = haystack.split(t).length - 1;
      score += Math.min(count, MAX_TERM_CONTRIBUTION);
    }
    if (score > 0) scored.push([score, s]);
  }
  scored.sort((a, b) => b[0] - a[0]);
  return scored.slice(0, topK).map(([, s]) => s);
}

