const FOLLOWUP_MARKER = "###FOLLOWUP_QUESTIONS_JSON###";

const ANSWERER_SYSTEM_PROMPT =
  "You are a careful assistant helping people in Germany understand " +
  "German employment and data-protection law - specifically the " +
  "Betriebsverfassungsgesetz (BetrVG, works council law) and the " +
  "Bundesdatenschutzgesetz (BDSG, federal data protection act, which " +
  "supplements the EU GDPR domestically). You will be given one or more " +
  "excerpts of official German legal text, each labeled with its law " +
  "abbreviation and § number, and a question, which may be written in " +
  "German or English. " +
  "IMPORTANT: Answer in the EXACT language requested by the user. " +
  "If the question is in German, answer entirely in German; if it is in " +
  "English, answer entirely in English. Do not mix languages. " +
  "Ground every claim in the excerpts provided and cite both the law " +
  "abbreviation and § number inline regardless of language (e.g. 'under " +
  "§ 87 BetrVG ...' / 'nach § 26 BDSG ...'). If the excerpts don't fully " +
  "answer the question, say so plainly rather than guessing. Do not " +
  "state opinions as certain legal conclusions - describe what the law " +
  "says and note where a lawyer, works council, or data protection " +
  "officer should be consulted for a binding answer. Keep the answer " +
  "focused and avoid unnecessary repetition.\n\n" +
  "You MUST always end your reply with a follow-up section, even for a " +
  "short answer: after your complete answer, on its own line write " +
  `exactly ${FOLLOWUP_MARKER} and then, on the next line, a JSON array ` +
  "of 2-3 short natural follow-up questions the user might reasonably " +
  "ask next about this same topic - in the SAME language as your " +
  `answer. Example ending: \n${FOLLOWUP_MARKER}\n` +
  '["Follow-up question one?", "Follow-up question two?"]\n' +
  "This follow-up section is required in every reply, with no " +
  "exceptions. Do not use this marker anywhere else, and do not mention " +
  "it or the follow-up questions within the answer itself.";

function splitAnswerAndFollowups(rawText) {
  const idx = rawText.indexOf(FOLLOWUP_MARKER);
  if (idx === -1) return [rawText.trim(), []];
  const answerPart = rawText.slice(0, idx).trim();
  const followupPart = rawText.slice(idx + FOLLOWUP_MARKER.length).trim();
  try {
    const parsed = JSON.parse(followupPart);
    if (Array.isArray(parsed)) {
      return [answerPart, parsed.map(String).filter((q) => q.trim()).slice(0, 3)];
    }
  } catch (e) {
    // Malformed trailing JSON should never break the actual answer.
  }
  return [answerPart, []];
}

function jsonResponse(payload, status = 200) {
  return new Response(JSON.stringify(payload), {
    status,
    headers: { "content-type": "application/json" },
  });
}

export default async (request) => {
  if (request.method !== "POST") {
    return jsonResponse({ detail: "Method not allowed" }, 405);
  }

  let body;
  try {
    body = await request.json();
  } catch (e) {
    return jsonResponse({ detail: "Invalid JSON body" }, 400);
  }

  const question = String(body && body.question ? body.question : "").trim();
  if (!question) {
    return jsonResponse({ detail: "question must not be empty" }, 400);
  }

  const language = detectLanguage(question);
  const disclaimer = DISCLAIMER[language];

  // Netlify Edge Functions must send response headers within ~40s; keep a
  // safety margin under that for the one LLM call this makes.
  const DEADLINE_BUDGET_MS = 33000;
  const deadline = Date.now() + DEADLINE_BUDGET_MS;

  try {
    // Wider net than the Python version's fallback (top_k=5): there's no
    // LLM selector call here to narrow candidates semantically first (see
    // file header), so lexical scoring alone is more likely to let a
    // genuinely relevant section fall just outside the cutoff. 6 (rather
    // than 8) trades a little of that recall margin for a smaller prompt -
    // free-tier token/quota pressure matters more here than it did before.
    const sections = lexicalSearch(question, language, 6);

    if (!sections.length) {
      return jsonResponse({
        answer: `${NO_MATCH_MESSAGE[language]} ${disclaimer}`,
        cited_sections: [],
        follow_up_questions: [],
        degraded: false,
        language,
      });
    }

    const excerpts = sections.map((s) => `${s.section} ${s.title_de}\n${s.text_de}`).join("\n\n");

    try {
      const messages = [
        { role: "system", content: ANSWERER_SYSTEM_PROMPT },
        {
          role: "user",
          content: `TARGET_LANGUAGE: ${language}\nEXCERPTS:\n${excerpts}\n\nQUESTION: ${question}`,
        },
      ];
      const result = await chatCompletion(messages, { temperature: 0.2, maxTokens: 1500, deadline });
      const [answerText, followUps] = splitAnswerAndFollowups(result.text);
      return jsonResponse({
        answer: `${answerText}\n\n---\n${disclaimer}`,
        cited_sections: sections,
        follow_up_questions: followUps,
        provider_used: result.provider,
        model_used: result.model,
        degraded: false,
        language,
      });
    } catch (err) {
      if (!(err instanceof AllProvidersExhaustedError)) throw err;
      const raw = sections.map((s) => `${s.section} ${s.title_de}:\n${s.text_de}`).join("\n\n");
      return jsonResponse({
        answer: `${ALL_PROVIDERS_EXHAUSTED_PREFIX[language]}\n\n${raw}\n\n---\n${disclaimer}`,
        cited_sections: sections,
        follow_up_questions: [],
        degraded: true,
        language,
      });
    }
  } catch (err) {
    return jsonResponse({ detail: `Unexpected server error: ${err.message}` }, 500);
  }
};

export const config = { path: "/api/chat" };
